{
  "name": "多轴电动位移台",
  "name_en": "Multi-axis Motorized Translation Stage",
  "manufacturer": "",
  "description": "一种带电机驱动的多轴精密位移装置，可进行绝对/相对移动、回零、设定原点和单位切换，常用于显微镜物镜或样品的精密定位、扫描和对准。",
  "description_en": "A motor-driven multi-axis precision translation device that supports absolute/relative motion, homing, defining a home position, and unit selection. It is commonly used for precise positioning, scanning, and alignment of microscope objectives or samples.",
  "tag_hints": [
    "motorized translation stage",
    "multi-axis motion control",
    "precision positioning",
    "objective positioning",
    "sample alignment",
    "absolute and relative motion",
    "homing"
  ],
  "actions": [
    {
      "action_name": "auto-get_position",
      "description": "获取当前位置。",
      "description_en": "Get the current position."
    },
    {
      "action_name": "auto-send_command",
      "description": "发送底层电机控制命令。",
      "description_en": "Send a low-level motor control command."
    },
    {
      "action_name": "auto-move_abs",
      "description": "移动到指定绝对坐标。",
      "description_en": "Move to a specified absolute coordinate."
    },
    {
      "action_name": "auto-move_rel",
      "description": "按给定位移做相对移动。",
      "description_en": "Perform a relative move by a specified displacement."
    },
    {
      "action_name": "auto-set_units",
      "description": "设置位移单位。",
      "description_en": "Set the displacement units."
    },
    {
      "action_name": "auto-define_home",
      "description": "定义当前位置为原点。",
      "description_en": "Define the current position as home."
    },
    {
      "action_name": "auto-go_home",
      "description": "移动到原点位置。",
      "description_en": "Move to the home position."
    },
    {
      "action_name": "auto-execute_motor",
      "description": "执行电机控制命令。",
      "description_en": "Execute a motor control command."
    },
    {
      "action_name": "auto-start_session",
      "description": "启动设备会话并初始化电机运动参数。",
      "description_en": "Start a device session and initialize motor motion settings."
    },
    {
      "action_name": "auto-end_session",
      "description": "结束设备会话并关闭电机。",
      "description_en": "End the device session and turn off the motor."
    },
    {
      "action_name": "auto-find_axis",
      "description": "识别或选择可用运动轴。",
      "description_en": "Identify or select available motion axes."
    }
  ]
}

